"""Shared preparation sequence for the Windows tasks.

A Windows task declares its initializer as
``initializers.windows.<module>:<ClassName>``.  The class derives from
:class:`BaseWindowsInitializer`, which runs a fixed sequence through the guest:

1. ``runtime_binding`` - the guest runtime answers a readiness probe.
2. ``binding_validation`` - every entry point the class and the task declare
   exists on the guest.
3. ``preparation`` - the class's own preparation, plus the setup steps the task
   declares (``run_powershell``, ``run_python``, ``wait``).
4. ``app_launch`` - the application is started from the first candidate that
   exists, through its shortcut or its executable.
5. ``settle`` - the application is given the declared time to settle.
6. ``start_state`` - the process is confirmed, and where the task depends on a
   stored state the class confirms that as well.

Every step is recorded as a timed stage in the result metadata.  The result is
``PASS`` when the starting point was established and ``ERROR`` when it was not;
the message names the piece that could not be established.
"""

from __future__ import annotations

import json
import time
from datetime import datetime, timezone
from typing import Any, Callable, Mapping, Sequence

from evaluators.cua_review.core.evaluation import BaseEvaluator, EvalResult, EvalStatus

DEFAULT_WAIT_MS = 2500
DEFAULT_LAUNCH_TIMEOUT_SECONDS = 30.0
PROCESS_POLL_INTERVAL_SECONDS = 0.5

#: Candidate locations a task may name for an application's executable.
SHORTCUT_ROOTS = (
    r"%USERPROFILE%\Desktop",
    r"%USERPROFILE%\OneDrive\Desktop",
    r"%APPDATA%\Microsoft\Windows\Start Menu\Programs",
    r"%PROGRAMDATA%\Microsoft\Windows\Start Menu\Programs",
)


class WindowsPreparationError(RuntimeError):
    """Raised when a preparation step cannot establish the starting point."""


