def _script_result(result: Mapping[str, Any], what: str) -> str:
    if int(result.get("returncode", -1)) != 0:
        detail = str(result.get("stderr") or result.get("error")
                     or result.get("stdout") or result.get("output") or "")
        raise WindowsPreparationError(f"{what} failed: {detail.strip()[:400]}")
    return str(result.get("stdout") or result.get("output") or "")


def run_python(controller: Any, code: str, timeout: float = 30) -> str:
    """Run Python inside the guest and return its output."""
    return _script_result(
        controller.run_python_script(code, timeout=int(timeout)), "guest python step")


def run_python_json(controller: Any, code: str, timeout: float = 30) -> Any:
    """Run Python inside the guest and decode its output as JSON."""
    output = run_python(controller, code, timeout).strip()
    try:
        return json.loads(output)
    except ValueError as exc:
        raise WindowsPreparationError(f"guest python step did not return JSON: {output[:200]}") from exc


def run_powershell(controller: Any, script: str, timeout: float = 60) -> str:
    """Run a PowerShell script inside the guest and return its output."""
    code = (
        "import subprocess, sys\n"
        f"completed = subprocess.run(['powershell', '-NoProfile', '-NonInteractive',\n"
        f"    '-ExecutionPolicy', 'Bypass', '-Command', {script!r}],\n"
        f"    capture_output=True, text=True, timeout={int(max(timeout - 5, 5))})\n"
        "sys.stdout.write(completed.stdout or '')\n"
        "sys.stderr.write(completed.stderr or '')\n"
        "raise SystemExit(completed.returncode)\n"
    )
    return _script_result(controller.run_python_script(code, timeout=int(timeout)),
                          "guest PowerShell step")


def existing_paths(controller: Any, paths: Sequence[str]) -> list[str]:
    """The subset of ``paths`` that exists on the guest, environment expanded."""
    if not paths:
        return []
    code = (
        "import json, os\n"
        f"candidates = {list(paths)!r}\n"
        "found = []\n"
        "for candidate in candidates:\n"
        "    expanded = os.path.expandvars(candidate)\n"
        "    if os.path.exists(expanded):\n"
        "        found.append(candidate)\n"
        "print(json.dumps(found))\n"
    )
    return [str(x) for x in run_python_json(controller, code, 20)]


def shortcut_candidates(name: str) -> list[str]:
    """Shortcut locations that may start an application of this name."""
    return [rf"{root}\{name}.lnk" for root in SHORTCUT_ROOTS]


def resolve_shortcuts(controller: Any, patterns: Sequence[str]) -> list[str]:
    """Full paths of the shortcuts on the guest that match any of ``patterns``."""
    if not patterns:
        return []
    code = (
        "import glob, json, os\n"
        f"roots = {list(SHORTCUT_ROOTS)!r}\n"
        f"patterns = {list(patterns)!r}\n"
        "found = []\n"
        "for root in roots:\n"
        "    expanded = os.path.expandvars(root)\n"
        "    if not os.path.isdir(expanded):\n"
        "        continue\n"
        "    for pattern in patterns:\n"
        "        for match in sorted(glob.glob(os.path.join(expanded, pattern))):\n"
        "            if match not in found:\n"
        "                found.append(match)\n"
        "print(json.dumps(found))\n"
    )
    return [str(x) for x in run_python_json(controller, code, 30)]


def stop_processes(controller: Any, names: Sequence[str]) -> str:
    """Stop the given processes so the application can be raised from the task's shortcut."""
    if not names:
        return "no process is declared"
    return run_powershell(
        controller,
        "$ErrorActionPreference = 'SilentlyContinue'\n"
        + "\n".join(f"Stop-Process -Name '{name}' -Force" for name in names)
        + "\nWrite-Output 'STOPPED'",
        timeout=60,
    ).strip()



def launch(controller: Any, target: str) -> str:
    """Start an application from a shortcut or an executable path."""
    return run_powershell(
        controller,
        "$ErrorActionPreference = 'Stop'\n"
        f"$launchTarget = [Environment]::ExpandEnvironmentVariables(\"{target}\")\n"
        "if (-not (Test-Path -LiteralPath $launchTarget)) { throw 'Resolved application launch path missing' }\n"
        "Start-Process -FilePath $launchTarget\n"
        "Write-Output 'LAUNCHED'",
        timeout=60,
    ).strip()


def running_processes(controller: Any, names: Sequence[str]) -> list[str]:
    """Process names from ``names`` that are currently running on the guest."""
    if not names:
        return []
    return [str(x) for x in run_python_json(controller, (
        "import json\n"
        "import subprocess\n"
        f"wanted = [n.casefold() for n in {list(names)!r}]\n"
        "completed = subprocess.run(['tasklist', '/FO', 'CSV', '/NH'],\n"
        "                           capture_output=True, text=True)\n"
        "running = []\n"
        "for line in (completed.stdout or '').splitlines():\n"
        "    parts = [p.strip('\"') for p in line.split('\",\"')]\n"
        "    if not parts:\n"
        "        continue\n"
        "    image = parts[0].strip('\"')\n"
        "    stem = image[:-4] if image.casefold().endswith('.exe') else image\n"
        "    if stem.casefold() in wanted:\n"
        "        running.append(stem)\n"
        "print(json.dumps(sorted(set(running))))\n"
    ), 30)]


def read_local_state(controller: Any, leveldb_dir: str, key: str) -> Any:
    """Read one JSON document from an Electron application's local store."""
    code = (
        "import json, os, re\n"
        f"directory = os.path.expandvars({leveldb_dir!r})\n"
        f"key = {key!r}\n"
        "documents = []\n"
        "if os.path.isdir(directory):\n"
        "    for name in sorted(os.listdir(directory)):\n"
        "        if not name.endswith(('.log', '.ldb')):\n"
        "            continue\n"
        "        try:\n"
        "            raw = open(os.path.join(directory, name), 'rb').read()\n"
        "        except OSError:\n"
        "            continue\n"
        "        text = raw.decode('utf-8', 'ignore')\n"
        "        for marker in (key, key.encode('utf-8').decode('utf-8')):\n"
        "            start = text.find(marker)\n"
        "            while start != -1:\n"
        "                brace = text.find('{', start)\n"
        "                if brace != -1:\n"
        "                    try:\n"
        "                        value, _ = json.JSONDecoder().raw_decode(text[brace:])\n"
        "                    except ValueError:\n"
        "                        value = None\n"
        "                    if isinstance(value, dict):\n"
        "                        documents.append(value)\n"
        "                start = text.find(marker, start + 1)\n"
        "print(json.dumps(documents[-1] if documents else None))\n"
    )
    return run_python_json(controller, code, 40)


