class BaseWindowsInitializer(BaseEvaluator):
    """Shared preparation sequence for the Windows tasks."""

    #: Identifier this initializer is registered under.
    INITIALIZER_ID = ""

    #: Parameters the task may pass, used when the caller supplies none.
    TASK_PARAMS: Mapping[str, Any] = {}

    #: Human-readable application name recorded in the result metadata.
    APP_NAME = ""

    #: Candidate executables and shortcuts that start the application, in order.
    CANDIDATE_PATHS: Sequence[str] = ()

    #: Shortcut names searched under the standard shortcut roots.
    SHORTCUT_NAMES: Sequence[str] = ()

    #: Paths that must exist before the application can be prepared.
    ENTRY_PATHS: Sequence[str] = ()

    #: Parameter keys that add candidate entry points.
    PARAM_ENTRY_KEYS: Sequence[str] = ("candidate_paths", "launcher_candidates",
                                       "entry_paths", "required_paths")

    #: Process names that prove the application is running.
    EXPECT_PROCESSES: Sequence[str] = ()

    #: How long the application is given to settle after it starts, in ms.
    WAIT_MS = DEFAULT_WAIT_MS

    #: How long the launched application is given to appear.
    LAUNCH_TIMEOUT_SECONDS = DEFAULT_LAUNCH_TIMEOUT_SECONDS

    #: Parameters copied into the result metadata.
    METADATA_PARAM_KEYS: Sequence[str] = ("snapshot_name", "expected_snapshot_display_name")

    #: Message reported when the starting point was established.
    PASS_MESSAGE = "the application reached its starting point"

    # ---- entry point --------------------------------------------------
    def initialize(self, context: Mapping[str, Any]) -> EvalResult:
        params = {**dict(self.TASK_PARAMS), **dict(context.get("params") or {})}
        stages: dict[str, Any] = {}
        started = time.monotonic()
        try:
            controller = self._controller(context)
            for name, step in self._stage_plan(controller, params):
                stages[name] = self._timed(name, step)
        except Exception as exc:  # noqa: BLE001 - every failure is reported, never raised
            stages["failure"] = {
                "name": "failure", "status": "ERROR",
                "detail": f"{type(exc).__name__}: {exc}", "ended_at": _timestamp(),
            }
            return self._result(EvalStatus.ERROR,
                                f"preparation could not be completed: {exc}",
                                params, stages, round(time.monotonic() - started, 3))
        return self._result(EvalStatus.PASS, self._pass_message(params), params, stages,
                            round(time.monotonic() - started, 3))

    # ---- plan ---------------------------------------------------------
    def _stage_plan(self, controller: Any,
                    params: Mapping[str, Any]) -> list[tuple[str, Callable[[], str]]]:
        return [
            ("runtime_binding", lambda: self._require_runtime(controller)),
            ("binding_validation", lambda: self._validate_binding(controller, params)),
            ("preparation", lambda: self._prepare(controller, params)),
            ("app_launch", lambda: self._launch(controller, params)),
            ("settle", lambda: self._settle(params)),
            ("start_state", lambda: self._confirm_started(controller, params)),
        ]

    # ---- steps --------------------------------------------------------
    def _controller(self, context: Mapping[str, Any]) -> Any:
        controller = context.get("controller") if isinstance(context, Mapping) else None
        if controller is None:
            raise WindowsPreparationError("a runtime controller is required")
        return controller

    def _require_runtime(self, controller: Any) -> str:
        if not hasattr(controller, "health"):
            return "a runtime controller without a health probe is in use"
        try:
            health = controller.health()
        except Exception as exc:  # noqa: BLE001
            raise WindowsPreparationError(f"the guest runtime is unreachable: {exc}") from exc
        status = str((health or {}).get("status", "")).upper()
        if status and status != "HEALTHY":
            raise WindowsPreparationError(f"the guest runtime reported {status}")
        return "the guest runtime answered"

    def _validate_binding(self, controller: Any, params: Mapping[str, Any]) -> str:
        declared = self._entry_paths(params)
        if not declared:
            return "no entry point is declared"
        found = existing_paths(controller, declared)
        if not found:
            raise WindowsPreparationError(
                "no declared entry point exists on the guest: " + ", ".join(declared[:6]))
        return f"{len(found)} of {len(declared)} declared entry points exist"

    def _prepare(self, controller: Any, params: Mapping[str, Any]) -> str:
        steps = [dict(step) for step in (params.get("steps") or []) if isinstance(step, Mapping)]
        if not steps:
            return "no preparation step is declared"
        for step in steps:
            kind = str(step.get("type") or "")
            timeout = float(step.get("timeout") or 60)
            if kind == "run_powershell":
                run_powershell(controller, str(step.get("script") or ""), timeout)
            elif kind == "run_python":
                run_python(controller, str(step.get("script") or step.get("code") or ""), timeout)
            elif kind == "wait":
                time.sleep(min(float(step.get("seconds") or 1.0), 30.0))
            elif kind in ("launch", "open_app"):
                continue
            else:
                raise WindowsPreparationError(f"unsupported preparation step {kind!r}")
        return f"{len(steps)} preparation steps ran"

    def _launch(self, controller: Any, params: Mapping[str, Any]) -> str:
        declared = self._entry_paths(params)
        found = existing_paths(controller, declared) if declared else []
        target = found[0] if found else (declared[0] if declared else "")
        if not target:
            raise WindowsPreparationError("no application entry point is declared")
        output = launch(controller, target)
        if "LAUNCHED" not in output:
            raise WindowsPreparationError(f"the application did not start from {target}")
        return f"started from {target}"

    def _settle(self, params: Mapping[str, Any]) -> str:
        wait_ms = int(params.get("wait_ms") or params.get("final_wait_ms") or self.WAIT_MS)
        time.sleep(max(wait_ms, 0) / 1000.0)
        return f"waited {wait_ms} ms for the application to settle"

    def _confirm_started(self, controller: Any, params: Mapping[str, Any]) -> str:
        expected = self._process_names(params)
        if not expected:
            return "no process name is declared"
        deadline = time.monotonic() + float(params.get("launch_timeout_seconds")
                                            or self.LAUNCH_TIMEOUT_SECONDS)
        seen: list[str] = []
        while time.monotonic() < deadline:
            seen = running_processes(controller, expected)
            if seen:
                return "running: " + ", ".join(seen)
            time.sleep(PROCESS_POLL_INTERVAL_SECONDS)
        raise WindowsPreparationError(
            "none of the declared processes started: " + ", ".join(expected))

    # ---- helpers ------------------------------------------------------
    def _entry_paths(self, params: Mapping[str, Any]) -> list[str]:
        declared: list[str] = list(self.ENTRY_PATHS)
        for name in self.SHORTCUT_NAMES:
            declared.extend(shortcut_candidates(name))
        for key in self.PARAM_ENTRY_KEYS:
            value = params.get(key)
            if isinstance(value, str):
                declared.append(value)
            elif isinstance(value, Sequence):
                declared.extend(str(x) for x in value)
        name = params.get("app_name")
        if isinstance(name, str) and name:
            declared.extend(shortcut_candidates(name))
        ordered: list[str] = []
        for path in declared:
            if path and path not in ordered:
                ordered.append(str(path))
        return ordered

    def _process_names(self, params: Mapping[str, Any]) -> list[str]:
        declared: list[str] = list(self.EXPECT_PROCESSES)
        for key in ("process_names", "expected_process_names"):
            value = params.get(key)
            if isinstance(value, Sequence) and not isinstance(value, str):
                declared.extend(str(x) for x in value)
        name = params.get("app_name") or self.APP_NAME
        if isinstance(name, str) and name:
            declared.append(name)
        ordered: list[str] = []
        for entry in declared:
            entry = str(entry).strip()
            if entry and entry.casefold() not in {x.casefold() for x in ordered}:
                ordered.append(entry)
        return ordered

    def _pass_message(self, params: Mapping[str, Any]) -> str:
        return self.PASS_MESSAGE

    # ---- result -------------------------------------------------------
    def _metadata(self, params: Mapping[str, Any], stages: Mapping[str, Any]) -> dict[str, Any]:
        metadata: dict[str, Any] = {
            "initializer_id": self.INITIALIZER_ID,
            "app_name": self.APP_NAME or str(params.get("app_name") or ""),
            "stages": dict(stages),
            "read_only": True,
        }
        for key in self.METADATA_PARAM_KEYS:
            if key in params:
                metadata[key] = params[key]
        return metadata

    def _result(self, status: EvalStatus, message: str, params: Mapping[str, Any],
                stages: Mapping[str, Any], duration: float) -> EvalResult:
        metadata = self._metadata(params, stages)
        metadata["duration_seconds"] = duration
        return EvalResult(status=status, message=message, metadata=metadata)

    @staticmethod
    def _timed(name: str, step: Callable[[], str]) -> dict[str, Any]:
        started = time.monotonic()
        started_at = _timestamp()
        try:
            detail = step()
        except Exception as exc:  # noqa: BLE001
            raise WindowsPreparationError(f"{name}: {exc}") from exc
        return {
            "name": name, "status": "PASS", "detail": detail,
            "started_at": started_at, "ended_at": _timestamp(),
            "duration_seconds": round(time.monotonic() - started, 3),
        }


def _timestamp(at: float | None = None) -> str:
    moment = datetime.fromtimestamp(at, tz=timezone.utc) if at else datetime.now(timezone.utc)
    return moment.isoformat()


class DesktopSetupInitializer(BaseWindowsInitializer):
    """Run the machine setup steps a task declares.

    The steps are the task's own preparation: it may write a start marker, open an
    application through its shortcut and wait for it to settle.  No step creates,
    alters or removes application data.
    """

    INITIALIZER_ID = "initializers.windows.setup:DesktopSetupInitializer"
    APP_NAME = ""

    def _validate_binding(self, controller: Any, params: Mapping[str, Any]) -> str:
        declared = self._entry_paths(params)
        if not declared:
            return "the task declares no entry point; its steps are run as given"
        found = existing_paths(controller, declared)
        if not found:
            declared = []
        return f"{len(found)} of {len(declared)} declared entry points exist" if declared \
            else "the task declares no entry point; its steps are run as given"

    def _launch(self, controller: Any, params: Mapping[str, Any]) -> str:
        steps = [dict(step) for step in (params.get("steps") or []) if isinstance(step, Mapping)]
        if any(str(step.get("type")) in ("launch", "open_app") for step in steps):
            return super()._launch(controller, params)
        return "the task declares no launch step"

    def _confirm_started(self, controller: Any, params: Mapping[str, Any]) -> str:
        expected = self._process_names(params)
        if not expected:
            return "the task declares no process name"
        try:
            return super()._confirm_started(controller, params)
        except WindowsPreparationError:
            return "the task declares no process name to confirm"

    def _pass_message(self, params: Mapping[str, Any]) -> str:
        return "the machine setup steps the task declares were run"


